def register(registry):
    registry.register_node({
        "type": "monitor/monitor_color",
        "category": "monitor",
        "display_name": "颜色监视",
        "color": "#06b6d4",
        "inputs": [{"name": "in", "type": "flow"}],
        "outputs": [
            {"name": "trigger", "type": "flow"},
            {"name": "timeout", "type": "flow"},
        ],
        "params_schema": {
            "mode": {"type": "string", "enum": ["screen", "window", "relative"], "default": "screen", "description": "坐标模式", "display_names": {"screen": "屏幕坐标", "window": "窗口坐标", "relative": "相对坐标(0~1)"}},
            "rect": {"type": "array", "format": "region", "default": [0, 0, 10, 10], "description": "检测区域[x,y,w,h]", "varRef": True},
            "hwnd_var": {"type": "string", "default": "", "description": "窗口句柄变量名", "showWhen": "mode=window,mode=relative", "varRef": True},
            "target_color": {"type": "string", "default": "#FF0000", "format": "color", "description": "目标颜色(点击选色)", "showWhen": "check_mode!=change", "varRef": True},
            "tolerance": {"type": "number", "default": 10, "description": "容差(0-255)，越大越宽松", "showWhen": "check_mode!=change", "varRef": True},
            "check_mode": {"type": "string", "enum": ["contain", "change", "area"], "default": "contain", "description": "检测模式", "display_names": {"contain": "包含匹配(有即可)", "change": "变化检测(帧间差异)", "area": "面积占比(比例阈值)"}},
            "sample_mode": {"type": "string", "enum": ["center", "mean", "max_diff"], "default": "center", "description": "采样模式", "showWhen": "check_mode=contain", "display_names": {"center": "中心点采样", "mean": "平均色采样", "max_diff": "最大差异采样"}},
            "change_threshold": {"type": "number", "default": 10, "description": "变化阈值", "showWhen": "check_mode=change", "varRef": True},
            "area_ratio_threshold": {"type": "number", "default": 0.5, "description": "面积占比阈值", "showWhen": "check_mode=area", "varRef": True},
            "interval": {"type": "number", "default": 100, "description": "检测间隔(ms)", "varRef": True},
            "timeout": {"type": "number", "default": 0, "description": "超时(ms, 0=无限等待)", "varRef": True},
            "trigger_mode": {"type": "string", "enum": ["appear", "disappear", "change", "absent"], "default": "appear", "description": "触发模式", "display_names": {"appear": "出现时触发", "disappear": "消失时触发(需先检测到)", "change": "变化时触发(有/无翻转)", "absent": "不存在即触发(无需先检测到)"}},
            "initial_check": {"type": "string", "enum": ["baseline", "trigger"], "default": "baseline", "description": "首帧行为(disappear/change模式)", "display_names": {"baseline": "记录基线(首帧不触发)", "trigger": "立即判断(首帧即可能触发)"}, "showWhen": "trigger_mode=disappear,trigger_mode=change"},
            "on_trigger": {"type": "string", "enum": ["branch", "stop_all", "stop_task", "pause_task", "resume_task"], "default": "branch", "description": "触发后行为", "display_names": {"branch": "走trigger分支", "stop_all": "停止所有任务", "stop_task": "停止指定任务", "pause_task": "暂停指定任务", "resume_task": "恢复指定任务"}},
            "target_task": {"type": "string", "default": "", "description": "目标任务ID(异步宏/子脚本节点)", "showWhen": "on_trigger=stop_task,pause_task,resume_task", "nodeRef": "script_block/call_script_async,script_block/exec_sub_script", "varRef": True},
            "auto_stop": {"type": "boolean", "default": True, "description": "触发后自动停止此监视器"},
            "recheck_delay_ms": {"type": "number", "default": 500, "description": "循环模式下再次检测的等待(ms)", "showWhen": "auto_stop=false", "varRef": True},
            "max_triggers": {"type": "number", "default": 0, "description": "最大触发次数(0=无限循环)", "showWhen": "auto_stop=false", "varRef": True},
            "auto_close_after_ms": {"type": "number", "default": 0, "description": "自动关闭超时(ms, 0=不关闭)", "showWhen": "auto_stop=false", "varRef": True},
        },
        "handler": "_handle_monitor_node",
    })

    registry.register_node({
        "type": "monitor/monitor_ocr",
        "category": "monitor",
        "display_name": "OCR监视",
        "color": "#06b6d4",
        "inputs": [{"name": "in", "type": "flow"}],
        "outputs": [
            {"name": "trigger", "type": "flow"},
            {"name": "timeout", "type": "flow"},
        ],
        "params_schema": {
            "mode": {"type": "string", "enum": ["screen", "window", "relative"], "default": "screen", "description": "坐标模式", "display_names": {"screen": "屏幕坐标", "window": "窗口坐标", "relative": "相对坐标(0~1)"}},
            "rect": {"type": "array", "format": "region", "default": [0, 0, 100, 30], "description": "检测区域[x,y,w,h]", "varRef": True},
            "hwnd_var": {"type": "string", "default": "", "description": "窗口句柄变量名", "showWhen": "mode=window,mode=relative", "varRef": True},
            "match_text": {"type": "string", "default": "", "description": "匹配文本(留空=仅识别)", "varRef": True},
            "match_mode": {"type": "string", "enum": ["contain", "exact", "regex", "number_gt", "number_lt", "number_eq"], "default": "contain", "description": "匹配模式", "display_names": {"contain": "包含(模糊)", "exact": "完全匹配(精确)", "regex": "正则表达式", "number_gt": "数值大于", "number_lt": "数值小于", "number_eq": "数值等于"}},
            "match_number": {"type": "number", "default": 0, "description": "比较数值", "showWhen": "match_mode=number_gt,number_lt,number_eq", "varRef": True},
            "cache_strategy": {"type": "string", "enum": ["frame_diff", "time_interval", "disabled"], "default": "disabled", "description": "缓存策略(减少重复识别)", "display_names": {"frame_diff": "帧差检测(变化时重识)", "time_interval": "时间间隔缓存", "disabled": "禁用缓存(每次都识)"}},
            "cache_interval_ms": {"type": "number", "default": 100, "description": "缓存间隔(ms)", "showWhen": "cache_strategy=time_interval", "varRef": True},
            "ocr_engine": {"type": "string", "enum": ["rapidocr_onnx"], "default": "rapidocr_onnx", "description": "OCR引擎(当前仅RapidOCR)", "display_names": {"rapidocr_onnx": "RapidOCR (ONNX)"}},
            "ocr_preload": {"type": "boolean", "default": True, "description": "启动时预加载OCR模型(避免首次调用卡顿)", "display_names": {"true": "是(推荐)", "false": "否"}},
            "ocr_affinity_core": {"type": "number", "default": -1, "minimum": -1, "maximum": 63, "description": "OCR专用核心(-1=不单独绑核, 设为>=0则OCR在指定核心运行)", "showWhen": "ocr_preload=true"},
            "interval": {"type": "number", "default": 200, "description": "检测间隔(ms)", "varRef": True},
            "timeout": {"type": "number", "default": 0, "description": "超时(ms, 0=无限等待)", "varRef": True},
            "trigger_mode": {"type": "string", "enum": ["appear", "disappear", "change", "absent"], "default": "appear", "description": "触发模式", "display_names": {"appear": "出现时触发", "disappear": "消失时触发(需先检测到)", "change": "变化时触发(有/无翻转)", "absent": "不存在即触发(无需先检测到)"}},
            "initial_check": {"type": "string", "enum": ["baseline", "trigger"], "default": "baseline", "description": "首帧行为(disappear/change模式)", "display_names": {"baseline": "记录基线(首帧不触发)", "trigger": "立即判断(首帧即可能触发)"}, "showWhen": "trigger_mode=disappear,trigger_mode=change"},
            "on_trigger": {"type": "string", "enum": ["branch", "stop_all", "stop_task", "pause_task", "resume_task"], "default": "branch", "description": "触发后行为", "display_names": {"branch": "走trigger分支", "stop_all": "停止所有任务", "stop_task": "停止指定任务", "pause_task": "暂停指定任务", "resume_task": "恢复指定任务"}},
            "target_task": {"type": "string", "default": "", "description": "目标任务ID(异步宏/子脚本节点)", "showWhen": "on_trigger=stop_task,pause_task,resume_task", "nodeRef": "script_block/call_script_async,script_block/exec_sub_script", "varRef": True},
            "auto_stop": {"type": "boolean", "default": True, "description": "触发后自动停止此监视器"},
            "recheck_delay_ms": {"type": "number", "default": 500, "description": "循环模式下再次检测的等待(ms)", "showWhen": "auto_stop=false", "varRef": True},
            "max_triggers": {"type": "number", "default": 0, "description": "最大触发次数(0=无限循环)", "showWhen": "auto_stop=false", "varRef": True},
            "auto_close_after_ms": {"type": "number", "default": 0, "description": "自动关闭超时(ms, 0=不关闭)", "showWhen": "auto_stop=false", "varRef": True},
            "store_var": {"type": "string", "default": "", "description": "存储识别到的原始文本", "varRef": True},
            "store_number": {"type": "string", "default": "", "description": "存储提取的数字值", "showWhen": "match_mode=number_gt,number_lt,number_eq", "varRef": True},
        },
        "handler": "_handle_monitor_node",
    })

    registry.register_node({
        "type": "monitor/monitor_timer",
        "category": "monitor",
        "display_name": "定时器",
        "color": "#06b6d4",
        "inputs": [{"name": "in", "type": "flow"}],
        "outputs": [
            {"name": "trigger", "type": "flow"},
            {"name": "timeout", "type": "flow"},
        ],
        "params_schema": {
            "interval": {"type": "number", "default": 1000, "description": "触发间隔(ms)，1000=每秒一次", "varRef": True},
            "on_trigger": {"type": "string", "enum": ["branch", "stop_all", "stop_task", "pause_task", "resume_task"], "default": "branch", "description": "触发后行为", "display_names": {"branch": "走trigger分支", "stop_all": "停止所有任务", "stop_task": "停止指定任务", "pause_task": "暂停指定任务", "resume_task": "恢复指定任务"}},
            "target_task": {"type": "string", "default": "", "description": "目标任务ID(异步宏/子脚本节点)", "showWhen": "on_trigger=stop_task,pause_task,resume_task", "nodeRef": "script_block/call_script_async,script_block/exec_sub_script", "varRef": True},
            "auto_stop": {"type": "boolean", "default": True, "description": "触发后自动停止此监视器"},
            "recheck_delay_ms": {"type": "number", "default": 500, "description": "循环模式下再次触发的等待(ms)", "showWhen": "auto_stop=false", "varRef": True},
            "max_triggers": {"type": "number", "default": 0, "description": "最大触发次数(0=无限循环)", "showWhen": "auto_stop=false", "varRef": True},
            "auto_close_after_ms": {"type": "number", "default": 0, "description": "自动关闭超时(ms, 0=不关闭)", "showWhen": "auto_stop=false", "varRef": True},
        },
        "handler": "_handle_monitor_node",
    })

    registry.register_node({
        "type": "monitor/monitor_time",
        "category": "monitor",
        "display_name": "时间监视",
        "color": "#06b6d4",
        "inputs": [{"name": "in", "type": "flow"}],
        "outputs": [
            {"name": "trigger", "type": "flow"},
            {"name": "timeout", "type": "flow"},
        ],
        "params_schema": {
            "hour": {"type": "number", "default": 8, "description": "目标小时(0-23)", "varRef": True},
            "minute": {"type": "number", "default": 0, "description": "目标分钟(0-59)", "varRef": True},
            "second": {"type": "number", "default": 0, "description": "目标秒(0-59)", "varRef": True},
            "next_day": {"type": "boolean", "default": False, "description": "若已过目标时间: 否=立即触发一次然后等次日, 是=等到次日", "display_names": {"true": "是(等到次日)", "false": "否(已过立刻触发一次)"}},
            "check_interval": {"type": "number", "default": 500, "description": "检查间隔(ms)", "varRef": True},
            "timeout": {"type": "number", "default": 0, "description": "超时(ms, 0=无限等待)", "varRef": True},
            "on_trigger": {"type": "string", "enum": ["branch", "stop_all", "stop_task", "pause_task", "resume_task"], "default": "branch", "description": "触发后行为", "display_names": {"branch": "走trigger分支", "stop_all": "停止所有任务", "stop_task": "停止指定任务", "pause_task": "暂停指定任务", "resume_task": "恢复指定任务"}},
            "target_task": {"type": "string", "default": "", "description": "目标任务ID(异步宏/子脚本节点)", "showWhen": "on_trigger=stop_task,pause_task,resume_task", "nodeRef": "script_block/call_script_async,script_block/exec_sub_script", "varRef": True},
            "auto_stop": {"type": "boolean", "default": True, "description": "触发后自动停止此监视器"},
            "recheck_delay_ms": {"type": "number", "default": 500, "description": "循环模式下再次检测的等待(ms)", "showWhen": "auto_stop=false", "varRef": True},
            "max_triggers": {"type": "number", "default": 0, "description": "最大触发次数(0=无限循环)", "showWhen": "auto_stop=false", "varRef": True},
            "auto_close_after_ms": {"type": "number", "default": 0, "description": "自动关闭超时(ms, 0=不关闭)", "showWhen": "auto_stop=false", "varRef": True},
        },
        "handler": "_handle_monitor_time",
    })
